const archiveRoot = new URL('./', document.baseURI).href;
window.ArchiveImage = url => {
  if (archiveEffects[url]) return archiveEffects[url];
  if (!url.startsWith(archiveRoot)) return url;
  return archiveEffects[decodeURIComponent(url.slice(archiveRoot.length))] || url;
};
window.THREE.DefaultLoadingManager.setURLModifier(window.ArchiveImage);
